<?php
$stmt=db()->prepare('SELECT * FROM notifikasi WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$stmt->execute([user_id()]);$rows=$stmt->fetchAll();$unread=count(array_filter($rows,fn($n)=>!$n['dibaca_pada']));
?>
<div class="page-heading"><div><h1>Notifikasi</h1><p><?= $unread ?> notifikasi belum dibaca. Informasi aktivitas akun dan layananmu.</p></div><?php if($unread): ?><form method="post" action="index.php"><?= csrf_field() ?><input type="hidden" name="action" value="mark_notifications"><input type="hidden" name="return_page" value="notifikasi"><button class="btn btn-outline-army">Tandai semua dibaca</button></form><?php endif; ?></div>
<div class="d-flex flex-column gap-2"><?php if(!$rows): ?><div class="panel-card empty-state"><i class="bi bi-bell-slash"></i><strong>Belum ada notifikasi</strong><span>Notifikasi baru akan muncul di sini.</span></div><?php else: foreach($rows as $n): ?><article class="panel-card p-3 d-flex gap-3 align-items-start <?= !$n['dibaca_pada']?'notification-unread':'' ?>"><span class="quick-action-icon"><i class="bi bi-<?= match($n['tipe']){'pengajuan'=>'file-earmark-text','keluhan'=>'chat-square-text','pengumuman'=>'megaphone','kegiatan'=>'calendar-event','akun'=>'person-plus',default=>'bell'} ?>"></i></span><div class="flex-grow-1"><strong class="d-block"><?= e($n['judul']) ?></strong><p class="text-muted-2 mb-1"><?= e($n['pesan']) ?></p><small class="text-muted-2"><?= e(format_datetime($n['created_at'])) ?></small></div><?php if(!$n['dibaca_pada']): ?><span class="unread-dot"></span><?php endif; ?><?php if($n['tautan']): ?><a class="btn btn-sm btn-outline-army" href="<?= e($n['tautan']) ?>">Buka</a><?php endif; ?></article><?php endforeach; endif; ?></div>
